(() => {
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],room=$('#room-dialog');
let selected='ali',peer=null,conn=null,isHost=false,roomCode='',remoteInput={},remoteAt=0,sendAccumulator=0,attempt=0,deadline=null,lastPacket=0,soundOn=false,audio=null,toastTimer,rematchRequested=false;
const setMessage=s=>$('#connection-message').textContent=s;
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500)}
function status(s,online=false){$('#network-status').textContent=s;$('#status-dot').classList.toggle('online',online)}
function choose(c){selected=c;localSlot=c==='ali'?0:1;$$('[data-character]').forEach(b=>{b.classList.toggle('selected',b.dataset.character===c);b.setAttribute('aria-pressed',String(b.dataset.character===c))});$('#selection-label').textContent=c.toUpperCase()+' SEÇİLDİ';$('#room-character').textContent=c==='ali'?'Ali':'Aslı';$('#ali-tag').textContent=c==='ali'?'SEN':'RAKİP';$('#asli-tag').textContent=c==='asli'?'SEN':'RAKİP'}
$$('[data-character]').forEach(b=>b.onclick=()=>{if(peer){toast('Karakter değiştirmek için önce odadan ayrıl.');return}choose(b.dataset.character);if(gameMode==='practice')startMatch('practice')});choose('ali');
$$('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#open-room').onclick=()=>{clearControls();room.showModal()};$('#help').onclick=()=>{clearControls();$('#help-dialog').showModal()};$('.close-help').onclick=()=>$('#help-dialog').close();$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
$$('[data-key]').forEach(b=>{const release=()=>controls[b.dataset.key]=false;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);controls[b.dataset.key]=true;unlockAudio()});['pointerup','pointercancel','lostpointercapture'].forEach(n=>b.addEventListener(n,release))});
function unlockAudio(){if(soundOn&&!audio)audio=new(window.AudioContext||window.webkitAudioContext)();audio?.resume()}
$('#sound').onclick=()=>{soundOn=!soundOn;unlockAudio();$('.sound-state').textContent=soundOn?'ON':'OFF';$('#sound').setAttribute('aria-label',soundOn?'Sesi kapat':'Sesi aç');if(soundOn)playTone('kiss')};
window.playTone=function(kind){if(!soundOn||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);const t=audio.currentTime;o.type=kind==='hit'?'triangle':'sine';o.frequency.setValueAtTime(kind==='hit'?170:kind==='win'?440:600,t);o.frequency.exponentialRampToValueAtTime(kind==='hit'?65:kind==='win'?880:1000,t+.13);g.gain.setValueAtTime(.065,t);g.gain.exponentialRampToValueAtTime(.001,t+.19);o.start(t);o.stop(t+.2)};
$('#practice').onclick=()=>{disconnect();startMatch('practice');status('ANTRENMAN MODU',true);unlockAudio()};
$('#rematch').onclick=()=>{if(gameMode==='practice'){startMatch('practice');return}if(conn?.open){if(isHost){startOnline()}else{send({type:'rematch'});$('#result-detail').textContent='Oda sahibinden rövanş bekleniyor…';rematchRequested=true}}};
function send(d){if(conn?.open)try{conn.send(d)}catch{connectionLost()}}
function disconnect(){attempt++;clearTimeout(deadline);deadline=null;const p=peer;peer=null;const c=conn;conn=null;c?.close();p?.destroy();remoteInput={};roomCode='';isHost=false;$('#room-ready').hidden=true;$('#create-room').disabled=false;$('#create-room').hidden=false;$('#join-button').disabled=false;$('#join-code').disabled=false;$('#leave-room').hidden=true;$$('[data-character]').forEach(b=>b.disabled=false);setMessage('Oda kurucusu sayfayı açık tutmalı.');status('OYUNCU BEKLENİYOR');if(gameMode==='online'){combat.reset();gameMode='idle';$('#arena-prompt').hidden=false;$('#result').hidden=true;$('#mode-label').textContent='SERBEST ANTRENMAN'} }
function connectionLost(){if(!peer)return;disconnect();toast('Bağlantı kesildi. Yeni oda oluşturup tekrar bağlanabilirsiniz.');status('BAĞLANTI KESİLDİ')}
$('#leave-room').onclick=()=>{disconnect();toast('Odadan ayrıldın.')};window.addEventListener('pagehide',()=>peer?.destroy());
function makePeer(code,host){disconnect();isHost=host;roomCode=code;combat.active=false;clearControls();const id=host?'kiss-fighter-v1-'+code:undefined;const myAttempt=++attempt;$('#create-room').disabled=true;$('#join-button').disabled=true;setMessage(host?'Odan hazırlanıyor…':'Odaya bağlanılıyor…');status('BAĞLANTI KURULUYOR');try{peer=new Peer(id,{debug:0})}catch{disconnect();setMessage('WebRTC başlatılamadı. Güncel Chrome veya Safari deneyin.');return}
const current=peer;deadline=setTimeout(()=>{if(myAttempt!==attempt)return;disconnect();setMessage('Bağlantı zaman aşımına uğradı. Kodu kontrol et veya farklı ağ dene.')},25000);
current.on('open',()=>{if(myAttempt!==attempt)return;if(host){clearTimeout(deadline);$('#room-ready').hidden=false;$('#room-code').textContent=code;$('#create-room').hidden=true;$('#leave-room').hidden=false;$('#join-code').disabled=true;$('#join-button').disabled=true;setMessage('Oda hazır. Kodu paylaş, arkadaşın bağlanınca maç başlayacak.');status('RAKİP BEKLENİYOR');$$('[data-character]').forEach(b=>b.disabled=true)}else{wire(current.connect('kiss-fighter-v1-'+code,{reliable:true,serialization:'json',metadata:{protocol:1}}),false,myAttempt)}});
current.on('connection',c=>{if(myAttempt!==attempt||!host||conn||c.metadata?.protocol!==1){c.close();return}wire(c,true,myAttempt)});
current.on('error',e=>{if(myAttempt!==attempt)return;const msg=e.type==='peer-unavailable'?'Oda bulunamadı. Kodu ve oda sahibinin çevrimiçi olduğunu kontrol et.':e.type==='unavailable-id'?'Bu oda kodu kullanımda. Yeniden oda oluştur.':'Bağlantı kurulamadı. Farklı bir ağ veya tarayıcı deneyin.';disconnect();setMessage(msg);status('BAĞLANTI KURULAMADI')});current.on('disconnected',()=>{if(current===peer){if(conn?.open){setMessage('Maç bağlantısı açık; oda servisiyle bağlantı kesildi.')}else connectionLost()}})
}
function wire(c,host,myAttempt){conn=c;if(host){deadline=setTimeout(()=>{if(myAttempt===attempt&&!c.open){c.close();conn=null;setMessage('Oyuncu bağlanamadı. Davet kodunu tekrar paylaş.')}},25000)}c.on('open',()=>{if(myAttempt!==attempt)return;clearTimeout(deadline);lastPacket=performance.now();$('#leave-room').hidden=false;$$('[data-character]').forEach(b=>b.disabled=true);status('İKİ KALP BAĞLANDI',true);if(host){send({type:'welcome',slot:1-localSlot,protocol:1});startOnline()}else{setMessage('Bağlandı. Savaşçın atanıyor…')}});
c.on('data',d=>{if(myAttempt!==attempt||!d||typeof d!=='object')return;lastPacket=performance.now();if(host){if(d.type==='input'&&d.keys&&typeof d.keys==='object'){remoteInput=Object.fromEntries(['left','right','jump','kiss'].map(k=>[k,d.keys[k]===true]));remoteAt=performance.now()}if(d.type==='rematch'&&combat.winner!==null){$('#result-detail').textContent='Arkadaşın rövanş istiyor. Hazırsan bir öpücük daha!';toast('Arkadaşın rövanş istiyor ♥')}}else{if(d.type==='welcome'&&d.protocol===1&&(d.slot===0||d.slot===1)){choose(d.slot===0?'ali':'asli');room.close();startMatch('online');status('İKİ KALP BAĞLANDI',true)}if(d.type==='start'){startMatch('online');room.close()}if(d.type==='state'&&validState(d.state)){Object.assign(combat,d.state)}}});c.on('close',()=>{if(myAttempt===attempt)connectionLost()});c.on('error',()=>{if(myAttempt===attempt)connectionLost()})}
function validState(s){return s&&Array.isArray(s.players)&&s.players.length===2&&s.players.every(p=>p&&['x','y','vy','hp','cd','hit','pose'].every(k=>Number.isFinite(p[k]))&&p.hp>=0&&p.hp<=100&&p.x>=0&&p.x<=1200&&p.y>=-1000&&p.y<=0)&&Array.isArray(s.hearts)&&s.hearts.length<=30&&s.hearts.every(h=>h&&['x','y','dir','owner','life','id'].every(k=>Number.isFinite(h[k]))&&(h.owner===0||h.owner===1))&&Number.isFinite(s.remaining)&&s.remaining>=0&&s.remaining<=90&&[null,0,1,'draw'].includes(s.winner)&&typeof s.active==='boolean'&&Number.isFinite(s.serial)}
function startOnline(){startMatch('online');remoteInput={};remoteAt=performance.now();rematchRequested=false;send({type:'start'});send({type:'state',state:combat.snapshot()});room.close()}
$('#create-room').onclick=()=>{const chars='ABCDEFGHJKMNPQRSTUVWXYZ23456789',n=crypto.getRandomValues(new Uint8Array(6));const code=[...n].map(x=>chars[x%chars.length]).join('');makePeer(code,true)};
$('#join-form').onsubmit=e=>{e.preventDefault();const code=$('#join-code').value.trim().toUpperCase();if(!/^[A-Z0-9]{6}$/.test(code)){setMessage('6 karakterli oda kodunu gir.');return}makePeer(code,false)};
async function copy(s){try{await navigator.clipboard.writeText(s);toast('Kopyalandı. Şimdi arkadaşına gönder ♥')}catch{toast('Kopyalanamadı. Oda kodunu seçip elle kopyalayabilirsin.')}}$('#copy-code').onclick=()=>copy(roomCode);$('#copy-link').onclick=()=>{const u=new URL(location.href);u.search='';u.searchParams.set('oda',roomCode);copy(u.href)};
window.stepGame=function(dt){if(gameMode==='practice'){const aiSlot=1-localSlot,p=combat.players[aiSlot],you=combat.players[localSlot],dx=you.x-p.x;const toward=Math.abs(dx)>390,away=Math.abs(dx)<225;const move=toward?Math.sign(dx):away?-Math.sign(dx):0;const danger=combat.hearts.some(h=>h.owner!==aiSlot&&Math.abs(h.x-p.x)<130&&Math.abs(h.y-(320+p.y))<65);const ai={left:move<0,right:move>0,kiss:Math.sin(performance.now()/530)>.1,jump:danger&&Math.sin(performance.now()/900)>.2};const ins=[];ins[localSlot]=controls;ins[aiSlot]=ai;combat.step(dt,ins)}else if(gameMode==='online'&&conn?.open){if(isHost){if(performance.now()-remoteAt>500)remoteInput={};const ins=[];ins[localSlot]=controls;ins[1-localSlot]=remoteInput;combat.step(dt,ins)}sendAccumulator+=dt;if(sendAccumulator>=.05){sendAccumulator=0;if(isHost)send({type:'state',state:combat.snapshot()});else send({type:'input',keys:{...controls}})}if(performance.now()-lastPacket>12000){connectionLost();toast('Oyuncudan yanıt alınamadı. Bağlantıyı yeniden kurun.')}}};
// Stop movement when modal opens; the opponent still sees the authoritative clock.
$$('dialog').forEach(d=>d.addEventListener('close',clearControls));
const invite=new URL(location.href).searchParams.get('oda');if(invite&&/^[a-zA-Z0-9]{6}$/.test(invite)){$('#join-code').value=invite.toUpperCase();room.showModal();setMessage('Davet kodun hazır. Katıl düğmesine bas.')}if(typeof Phaser==='undefined')toast('Oyun motoru yüklenemedi. Sayfayı yenile.');
})();
